/** Public entry point for the data-grid-find-replace add-on — the only module consumers should import from. */

export {
  useDataGridFindReplace,
  type UseDataGridFindReplaceOptions,
  type UseDataGridFindReplaceResult,
} from "./use-data-grid-find-replace";
export { planReplace, type ReplaceOptions, type ReplacePlan, type ReplaceSkipReason, type ReplaceState } from "./plan-replace";

"use client";

import { useEffect, useMemo, useState, type ComponentType } from "react";
import type { DataGridPlugin } from "@/registry/default/components/data-grid/data-grid";
import { FindReplacePanel, type PanelStore } from "./find-replace-panel";
import type { ReplaceOptions } from "./plan-replace";

export type UseDataGridFindReplaceOptions = Pick<ReplaceOptions, "scope" | "replaceAllLimit">;

export type UseDataGridFindReplaceResult = {
  /** One entry of the grid's `plugins` prop: the panel, the `openFindReplace` command, and its `ctrl+h` binding. */
  plugin: DataGridPlugin<unknown>;
  /** Opens the panel; `"replace"` (default) shows the Replace field, `"find"` hides it. */
  open: (mode?: "find" | "replace") => void;
  close: () => void;
};

function createPanelStore(): PanelStore {
  const listeners = new Set<() => void>();
  let state = { open: false, mode: "replace" as "find" | "replace", openCount: 0 };
  let options: ReplaceOptions = {};
  return {
    getOptions: () => options,
    setOptions(next) {
      options = next;
    },
    getState: () => state,
    subscribe(listener) {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
    open(mode) {
      state = { open: true, mode, openCount: state.openCount + 1 };
      listeners.forEach((listener) => listener());
    },
    close() {
      if (!state.open) return;
      state = { ...state, open: false };
      listeners.forEach((listener) => listener());
    },
  };
}

/**
 * Find and replace for a grid: a panel with Find and Replace fields that shares the quick search
 * (highlights, next/previous) and writes through each column's text codec as one undoable change.
 * Pass `plugin` in the grid's `plugins`; `ctrl+h` opens the panel.
 */
export function useDataGridFindReplace(options: UseDataGridFindReplaceOptions = {}): UseDataGridFindReplaceResult {
  const [panelStore] = useState(createPanelStore);
  useEffect(() => {
    panelStore.setOptions(options);
  });

  const plugin = useMemo<DataGridPlugin<unknown>>(() => {
    const Mount: ComponentType = function FindReplaceMount() {
      return <FindReplacePanel panelStore={panelStore} />;
    };
    return {
      name: "find-replace",
      Mount,
      commands: {
        openFindReplace: {
          label: "Find and replace",
          group: "other",
          run: (ctx) => panelStore.open(ctx.readOnly ? "find" : "replace"),
        },
      },
      keymap: { openFindReplace: ["ctrl+h"] },
    };
  }, [panelStore]);

  return useMemo(
    () => ({ plugin, open: (mode = "replace") => panelStore.open(mode), close: () => panelStore.close() }),
    [plugin, panelStore],
  );
}

"use client";

import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  useSyncExternalStore,
  type KeyboardEvent as ReactKeyboardEvent,
  type ReactNode,
} from "react";
import { createPortal } from "react-dom";
import { ChevronDown, ChevronUp, X } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
  useDataGridApi,
  useDataGridLabels,
  useDataGridReadOnly,
  useDataGridScrollToCellAt,
  useDataGridSearchText,
} from "@/registry/default/components/data-grid/data-grid";
import {
  GRID_ATTR,
  isComposingKey,
  useDataGridInstanceId,
  useDataGridSearchCapped,
  useDataGridSearchMatches,
} from "@/registry/default/components/data-grid/data-grid-sdk";
import { MAX_REPLACE_INPUT_LENGTH, planReplace, type ReplaceOptions } from "./plan-replace";

export type PanelStore = {
  getOptions(): ReplaceOptions;
  setOptions(options: ReplaceOptions): void;
  getState(): { open: boolean; mode: "find" | "replace"; openCount: number };
  subscribe(listener: () => void): () => void;
  open(mode: "find" | "replace"): void;
  close(): void;
};

type PanelProps = { panelStore: PanelStore };

type Status = { kind: "replaced"; replaced: number; skipped: number; more: boolean } | { kind: "validating" } | null;

const SEARCH_DEBOUNCE_MS = 150;

export function FindReplacePanel({ panelStore }: PanelProps): ReactNode {
  const { open, mode, openCount } = useSyncExternalStore(panelStore.subscribe, panelStore.getState, panelStore.getState);
  if (!open) return null;
  return createPortal(<PanelBody key={openCount} panelStore={panelStore} showReplace={mode === "replace"} />, document.body);
}

function PanelBody({ panelStore, showReplace }: PanelProps & { showReplace: boolean }): ReactNode {
  const api = useDataGridApi();
  const labels = useDataGridLabels().findReplace;
  const readOnly = useDataGridReadOnly();
  const instanceId = useDataGridInstanceId();
  const matches = useDataGridSearchMatches();
  const capped = useDataGridSearchCapped();
  const searchedText = useDataGridSearchText();
  const scrollToCell = useDataGridScrollToCellAt();

  const [find, setFind] = useState(() => api.store.getState().searchText);
  const [replacement, setReplacement] = useState("");
  const [searchOptions, setSearchOptions] = useState(() => api.store.getState().searchOptions);
  const [cursor, setCursor] = useState(0);
  const [status, setStatus] = useState<Status>(null);
  const [position, setPosition] = useState<{ top: number; right: number }>({ top: 8, right: 8 });
  const findRef = useRef<HTMLInputElement | null>(null);
  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const settleRef = useRef<(() => void) | null>(null);

  useEffect(() => {
    findRef.current?.focus();
    findRef.current?.select();
    return () => {
      if (debounceRef.current) clearTimeout(debounceRef.current);
      settleRef.current?.();
    };
  }, []);

  useLayoutEffect(() => {
    const place = () => {
      const grid = document.querySelector(`[${GRID_ATTR.instance}="${CSS.escape(instanceId)}"]`);
      if (!grid) return;
      const rect = grid.getBoundingClientRect();
      setPosition({ top: Math.max(8, rect.top + 8), right: Math.max(8, window.innerWidth - rect.right + 24) });
    };
    place();
    window.addEventListener("resize", place);
    window.addEventListener("scroll", place, true);
    return () => {
      window.removeEventListener("resize", place);
      window.removeEventListener("scroll", place, true);
    };
  }, [instanceId]);

  const runSearch = useCallback(
    (text: string, options: { matchCase: boolean; wholeCell: boolean }) => {
      if (debounceRef.current) clearTimeout(debounceRef.current);
      api.actions.setSearch(text, options);
    },
    [api],
  );

  const goTo = useCallback(
    (index: number) => {
      const list = api.store.getState().searchMatches;
      if (list.length === 0) return;
      const wrapped = ((index % list.length) + list.length) % list.length;
      setCursor(wrapped);
      const match = list[wrapped]!;
      const col = api.store.getState().visibleColumns.findIndex((c) => c.id === match.columnId);
      if (col === -1) return;
      api.actions.setActiveCellAt({ col, row: match.row });
      scrollToCell({ col, row: match.row });
    },
    [api, scrollToCell],
  );

  const onFindChange = (text: string) => {
    setFind(text);
    setStatus(null);
    if (debounceRef.current) clearTimeout(debounceRef.current);
    debounceRef.current = setTimeout(() => runSearch(text, searchOptions), SEARCH_DEBOUNCE_MS);
  };

  const toggle = (key: "matchCase" | "wholeCell") => {
    const next = { ...searchOptions, [key]: !searchOptions[key] };
    setSearchOptions(next);
    setStatus(null);
    runSearch(find, next);
  };

  const canReplace = !readOnly && find.trim() !== "";

  const refOfMatch = (): { rowId: string; columnId: string } | null => {
    const s = api.store.getState();
    const active = s.activeCell;
    const activeColumnId = active ? s.visibleColumns[active.col]?.id : undefined;
    const onActive = active && s.searchMatches.find((m) => m.row === active.row && m.columnId === activeColumnId);
    const match = onActive || s.searchMatches[cursor];
    if (!match) return null;
    const dataIndex = s.viewIndex[match.row];
    const row = dataIndex === undefined ? undefined : s.data[dataIndex];
    if (dataIndex === undefined || row === undefined) return null;
    return { rowId: s.getRowId(row, dataIndex), columnId: match.columnId };
  };

  const apply = (only: { rowId: string; columnId: string } | undefined) => {
    const s = api.store.getState();
    if (s.readOnly || s.editing !== null || find.trim() === "") return;
    const plan = planReplace(s, find, replacement, { ...panelStore.getOptions(), ...searchOptions, only });
    const dataBefore = s.data;
    const verdict = plan.patches.length === 0 ? null : api.actions.updateCells(plan.patches, { source: "replace", reorder: "defer" });
    if (verdict?.pending) {
      setStatus({ kind: "validating" });
      settleRef.current?.();
      const unsubscribe = api.store.subscribe((next) => {
        if (next.data === dataBefore) return;
        settleRef.current?.();
        setStatus(null);
        runSearch(find, searchOptions);
      });
      settleRef.current = () => {
        unsubscribe();
        settleRef.current = null;
      };
      return;
    }
    setStatus({
      kind: "replaced",
      replaced: verdict?.applied ?? 0,
      skipped: plan.skipped.length + (verdict?.skipped.length ?? 0),
      more: plan.remaining,
    });
    runSearch(find, searchOptions);
    if (only) {
      const left = api.store.getState().searchMatches.length;
      if (left > 0) goTo(Math.min(cursor, left - 1));
    }
  };

  const replaceOne = () => {
    const ref = refOfMatch();
    if (ref) apply(ref);
  };

  const onKeyDown = (event: ReactKeyboardEvent<HTMLDivElement>) => {
    event.stopPropagation();
    if (isComposingKey(event)) return;
    if (event.key === "Escape") {
      event.preventDefault();
      panelStore.close();
      api.focus();
    }
  };

  const onFindKeyDown = (event: ReactKeyboardEvent<HTMLInputElement>) => {
    if (event.key !== "Enter" || isComposingKey(event)) return;
    event.preventDefault();
    if (debounceRef.current) runSearch(find, searchOptions);
    goTo(cursor + (event.shiftKey ? -1 : 1));
  };

  const onReplaceKeyDown = (event: ReactKeyboardEvent<HTMLInputElement>) => {
    if (event.key !== "Enter" || isComposingKey(event) || !canReplace) return;
    event.preventDefault();
    if (event.ctrlKey || event.metaKey) apply(undefined);
    else replaceOne();
  };

  const hasMatches = matches.length > 0;
  const statusText = (() => {
    if (status?.kind === "validating") return labels.validating;
    if (status?.kind === "replaced") return status.more ? `${labels.replaced(status.replaced, status.skipped)}. ${labels.moreRemain}` : labels.replaced(status.replaced, status.skipped);
    if (find.trim() === "" || searchedText !== find) return "";
    return hasMatches ? labels.position(Math.min(cursor, matches.length - 1) + 1, matches.length, capped) : labels.noMatches;
  })();

  return (
    <div
      role="dialog"
      aria-label={labels.dialogLabel}
      onKeyDown={onKeyDown}
      onCopy={(event) => event.stopPropagation()}
      onCut={(event) => event.stopPropagation()}
      onPaste={(event) => event.stopPropagation()}
      style={{ position: "fixed", top: position.top, right: position.right, zIndex: 50 }}
      className="flex w-80 flex-col gap-2 rounded-md border border-border bg-popover p-2 text-sm text-popover-foreground shadow-md"
    >
      <div className="flex items-center gap-1">
        <Input
          ref={findRef}
          value={find}
          maxLength={MAX_REPLACE_INPUT_LENGTH}
          onChange={(event) => onFindChange(event.target.value)}
          onKeyDown={onFindKeyDown}
          aria-label={labels.findLabel}
          placeholder={labels.findLabel}
          className="h-8"
        />
        <Button type="button" variant="ghost" size="icon-sm" aria-label={labels.previous} disabled={!hasMatches} onClick={() => goTo(cursor - 1)}>
          <ChevronUp />
        </Button>
        <Button type="button" variant="ghost" size="icon-sm" aria-label={labels.next} disabled={!hasMatches} onClick={() => goTo(cursor + 1)}>
          <ChevronDown />
        </Button>
        <Button type="button" variant="ghost" size="icon-sm" aria-label={labels.close} onClick={() => { panelStore.close(); api.focus(); }}>
          <X />
        </Button>
      </div>
      {showReplace && (
        <div className="flex items-center gap-1">
          <Input
            value={replacement}
            maxLength={MAX_REPLACE_INPUT_LENGTH}
            onChange={(event) => setReplacement(event.target.value)}
            onKeyDown={onReplaceKeyDown}
            aria-label={labels.replaceLabel}
            placeholder={labels.replaceLabel}
            disabled={readOnly}
            className="h-8"
          />
        </div>
      )}
      <div className="flex flex-wrap items-center gap-1">
        <Button type="button" size="sm" variant={searchOptions.matchCase ? "secondary" : "outline"} aria-pressed={searchOptions.matchCase} onClick={() => toggle("matchCase")}>
          {labels.matchCase}
        </Button>
        <Button type="button" size="sm" variant={searchOptions.wholeCell ? "secondary" : "outline"} aria-pressed={searchOptions.wholeCell} onClick={() => toggle("wholeCell")}>
          {labels.wholeCell}
        </Button>
        {showReplace && (
          <>
            <Button type="button" size="sm" disabled={!canReplace || !hasMatches} onClick={replaceOne}>
              {labels.replace}
            </Button>
            <Button type="button" size="sm" disabled={!canReplace || !hasMatches} onClick={() => apply(undefined)}>
              {labels.replaceAll}
            </Button>
          </>
        )}
      </div>
      <div role="status" aria-live="polite" className="min-h-4 text-xs text-muted-foreground">
        {statusText}
      </div>
    </div>
  );
}

import { type AnyColumnDef, type CellPatch, type CellRef, type SearchOptions } from "@/registry/default/components/data-grid/data-grid";
import { createTextMatcher, selectionContainsCell, toSafeText, type DataGridReadState } from "@/registry/default/components/data-grid/data-grid-sdk";

/** Longest find or replacement text; longer input is cut. */
export const MAX_REPLACE_INPUT_LENGTH = 1_000;
/** Longest text one replaced cell may reach. */
export const MAX_REPLACED_CELL_LENGTH = 100_000;
const DEFAULT_REPLACE_ALL_LIMIT = 10_000;
const MAX_REPLACE_ALL_LIMIT = 100_000;

/** What `planReplace` reads from the grid. */
export type ReplaceState = Pick<DataGridReadState, "data" | "viewIndex" | "visibleColumns" | "cellTypes" | "getRowId" | "selection">;

export type ReplaceOptions = SearchOptions & {
  /** `"view"` (default) covers every visible column of the rows in the view; `"selection"` covers the selected cells. */
  scope?: "view" | "selection";
  /** Most cells one plan targets; default 10,000, clamped to 1..100,000. */
  replaceAllLimit?: number;
};

export type ReplaceSkipReason = "readonly" | "unparseable" | "too-long";

export type ReplacePlan = {
  patches: CellPatch[];
  skipped: { ref: CellRef; reason: ReplaceSkipReason }[];
  /** True when the limit stopped the scan and more cells match. */
  remaining: boolean;
};

type ColumnPlan = {
  column: AnyColumnDef;
  readValue: (row: unknown) => unknown;
  readText: (value: unknown) => string;
  fromText: (text: string) => unknown;
  isEmpty: (value: unknown) => boolean;
};

function planColumn(column: AnyColumnDef, cellTypes: ReplaceState["cellTypes"]): ColumnPlan | null {
  const cellType = cellTypes[column.type ?? "text"];
  if (!cellType || cellType.activate) return null;
  const toText = cellType.toSearchText ?? cellType.toText;
  const options = column.options;
  const { accessorFn, accessorKey } = column;
  return {
    column,
    readValue: accessorFn ? (row) => accessorFn(row) : (row) => (row as Record<string, unknown>)[accessorKey as string],
    readText: (value) => {
      if (value == null) return "";
      try {
        return toSafeText(toText(value, options));
      } catch {
        return toSafeText(value);
      }
    },
    fromText: (text) => cellType.fromText(text, options),
    isEmpty: (value) => cellType.isEmpty(value),
  };
}

function isReadOnly(column: AnyColumnDef, row: unknown): boolean {
  if (!column.setValue && !column.accessorKey) return true;
  return typeof column.readOnly === "function" ? column.readOnly(row) : Boolean(column.readOnly);
}

/** Replaces every occurrence of `needle` in `text`, or returns `null` when the result would pass the cell cap. */
function replaceOccurrences(text: string, needle: string, replacement: string, matchCase: boolean): string | null {
  const haystack = matchCase ? text : text.toLowerCase();
  const target = matchCase ? needle : needle.toLowerCase();
  const sameLength = haystack.length === text.length;
  const starts: number[] = [];
  let projected = text.length;
  const step = needle.length;
  for (let from = 0; ; ) {
    const at = sameLength ? haystack.indexOf(target, from) : indexOfFolded(text, target, step, from);
    if (at === -1) break;
    starts.push(at);
    projected += replacement.length - step;
    if (projected > MAX_REPLACED_CELL_LENGTH) return null;
    from = at + step;
  }
  let out = "";
  let cursor = 0;
  for (const at of starts) {
    out += text.slice(cursor, at) + replacement;
    cursor = at + step;
  }
  return out + text.slice(cursor);
}

/** Case-insensitive search in text whose lowercase form changes length: compares same-length windows. */
function indexOfFolded(text: string, foldedNeedle: string, width: number, from: number): number {
  for (let at = from; at + width <= text.length; at++) {
    if (text.slice(at, at + width).toLowerCase() === foldedNeedle) return at;
  }
  return -1;
}

/**
 * Plans a replace over the grid: the cells whose search text matches `find`, each with the value
 * its type parses from the replaced text. Pure — the caller writes the patches. Hole rows, hidden
 * columns, and filtered-out rows never appear; read-only cells and results the type cannot parse
 * are reported in `skipped`.
 */
export function planReplace(
  state: ReplaceState,
  find: string,
  replacement: string,
  options: ReplaceOptions & { only?: CellRef } = {},
): ReplacePlan {
  const plan: ReplacePlan = { patches: [], skipped: [], remaining: false };
  const needle = find.slice(0, MAX_REPLACE_INPUT_LENGTH).trim();
  const isMatch = createTextMatcher(needle, options);
  if (isMatch === null) return plan;

  const { matchCase = false, wholeCell = false, scope = "view", only } = options;
  const to = replacement.slice(0, MAX_REPLACE_INPUT_LENGTH);
  const limit = Math.min(Math.max(Math.floor(options.replaceAllLimit ?? DEFAULT_REPLACE_ALL_LIMIT) || 1, 1), MAX_REPLACE_ALL_LIMIT);
  const columns = state.visibleColumns.map((column) => planColumn(column, state.cellTypes));

  const visit = (colIndex: number, rowId: string, row: unknown): boolean => {
    const entry = columns[colIndex];
    if (!entry) return true;
    const text = entry.readText(entry.readValue(row));
    if (!isMatch(text)) return true;
    const ref = { rowId, columnId: entry.column.id };
    if (isReadOnly(entry.column, row)) {
      plan.skipped.push({ ref, reason: "readonly" });
      return true;
    }
    const next = wholeCell ? to : replaceOccurrences(text, needle, to, matchCase);
    if (next === null) {
      plan.skipped.push({ ref, reason: "too-long" });
      return true;
    }
    if (next === text) return true;
    const value = entry.fromText(next);
    if (next.trim() !== "" && entry.isEmpty(value)) {
      plan.skipped.push({ ref, reason: "unparseable" });
      return true;
    }
    if (plan.patches.length >= limit) {
      plan.remaining = true;
      return false;
    }
    plan.patches.push({ ...ref, value });
    return true;
  };

  const { viewIndex, data } = state;
  const onlySelected = scope === "selection";
  for (let viewRow = 0; viewRow < viewIndex.length; viewRow++) {
    const dataIndex = viewIndex[viewRow]!;
    const row = data[dataIndex];
    if (row === undefined) continue;
    const rowId = state.getRowId(row, dataIndex);
    if (only && only.rowId !== rowId) continue;
    for (let col = 0; col < columns.length; col++) {
      if (only && only.columnId !== state.visibleColumns[col]!.id) continue;
      if (onlySelected && !selectionContainsCell(state.selection, { row: viewRow, col })) continue;
      if (!visit(col, rowId, row)) return plan;
    }
    if (only) return plan;
  }
  return plan;
}
